# Quick Lookup Dictionary for Normalization
CODE_LOOKUP_MAP = {}

for _opt in POST_RESPONSE_OPTIONS + GET_RESPONSE_OPTIONS + DELETE_RESPONSE_OPTIONS:
    if " - " in _opt and _opt not in ("Timeout - Polling", "Timeout", "No Response"):
        _parts = _opt.split(" - ", 2)
        _status = _parts[0]
        _code = _parts[1]
        _msg = _parts[2] if len(_parts) > 2 else ""
        
        # Key by "STATUS", "CODE", "STATUS - CODE"
        if _status not in CODE_LOOKUP_MAP:
            CODE_LOOKUP_MAP[_status] = _opt
        if f"{_status} - {_code}" not in CODE_LOOKUP_MAP:
            CODE_LOOKUP_MAP[f"{_status} - {_code}"] = _opt


def normalize_code(mode: str, default_fallback: str) -> str:
    if not mode:
        return default_fallback
    mode_str = str(mode).strip()
    while mode_str.endswith("-") or mode_str.endswith(" "):
        mode_str = mode_str[:-1].strip()
    if mode_str in CODE_LOOKUP_MAP:
        return CODE_LOOKUP_MAP[mode_str]
    return mode_str
